static int __fts5_expr_isspace(char t){
  return t==' ' || t=='\t' || t=='\n' || t=='\r';
}

/*
** Read the first token from the nul-terminated string at *pz.
*/
static int __fts5_expr_get_token(
  fts5_parse_t *parser, 
  const char **pz,                /* IN/OUT: Pointer into buffer */
  fts5_token_t *token
){
  const char *z = *pz;
  int tok;

  /* Skip past any whitespace */
  while( __fts5_expr_isspace(*z) ) z++;

  token->p = z;
  token->n = 1;
  switch( *z ){
    case '(':  tok = FTS5_LP;    break;
    case ')':  tok = FTS5_RP;    break;
    case '{':  tok = FTS5_LCP;   break;
    case '}':  tok = FTS5_RCP;   break;
    case ':':  tok = FTS5_COLON; break;
    case ',':  tok = FTS5_COMMA; break;
    case '+':  tok = FTS5_PLUS;  break;
    case '*':  tok = FTS5_STAR;  break;
    case '-':  tok = FTS5_MINUS; break;
    case '^':  tok = FTS5_CARET; break;
    case '\0': tok = FTS5_EOF;   break;

    case '"': {
      const char *z2;
      tok = FTS5_STRING;

      for(z2=&z[1]; 1; z2++){
        if( z2[0]=='"' ){
          z2++;
          if( z2[0]!='"' ) break;
        }
        if( z2[0]=='\0' ){
          __fts5_parse_error(parser, "unterminated string");
          return FTS5_EOF;
        }
      }
      token->n = (z2 - z);
      break;
    }

    default: {
      const char *z2;
      if( __fts5_is_bareword(z[0])==0 ){
        __fts5_parse_error(parser, "fts5: syntax error near \"%.1s\"", z);
        return FTS5_EOF;
      }
      tok = FTS5_STRING;
      for(z2=&z[1]; __fts5_is_bareword(*z2); z2++);
      token->n = (z2 - z);
      if( token->n==2 && memcmp(token->p, "OR", 2)==0 )  tok = FTS5_OR;
      if( token->n==3 && memcmp(token->p, "NOT", 3)==0 ) tok = FTS5_NOT;
      if( token->n==3 && memcmp(token->p, "AND", 3)==0 ) tok = FTS5_AND;
      break;
    }
  }

  *pz = &token->p[token->n];
  return tok;
}

