/*
** This function is only called when using the special 'trigram' tokenizer.
** Argument text contains the text of a LIKE or GLOB pattern matched
** against column i_col. This function creates and compiles an FTS5 MATCH
** expression that will match a superset of the rows matched by the LIKE or
** GLOB. If successful, DBSQL_OK is returned. Otherwise, an dbsql error
** code.
*/
static int __fts5_expr_pattern(
  fts5_config_t *config, int glob, int i_col, const char *text, fts5_expr_t **pp
){
  int64_t n_text = strlen(text);
  char *expr = (char*)dbsql_malloc64(n_text*4 + 1);
  int rc = DBSQL_OK;

  if( expr==0 ){
    rc = DBSQL_NOMEM;
  }else{
    char specs[3];
    int i_out = 0;
    int i = 0;
    int i_first = 0;

    if( glob==0 ){
      specs[0] = '_';
      specs[1] = '%';
      specs[2] = 0;
    }else{
      specs[0] = '*';
      specs[1] = '?';
      specs[2] = '[';
    }

    while( i<=n_text ){
      if( i==n_text 
       || text[i]==specs[0] || text[i]==specs[1] || text[i]==specs[2] 
      ){

        if( __fts5_expr_count_char(&text[i_first], i-i_first)>=3 ){
          int jj;
          expr[i_out++] = '"';
          for(jj=i_first; jj<i; jj++){
            expr[i_out++] = text[jj];
            if( text[jj]=='"' ) expr[i_out++] = '"';
          }
          expr[i_out++] = '"';
          expr[i_out++] = ' ';
        }
        if( text[i]==specs[2] ){
          i += 2;
          if( text[i-1]=='^' ) i++;
          while( i<n_text && text[i]!=']' ) i++;
        }
        i_first = i+1;
      }
      i++;
    }
    if( i_out>0 ){
      int and = 0;
      if( config->detail!=FTS5_DETAIL_FULL ){
        and = 1;
        if( config->detail==FTS5_DETAIL_NONE ){
          i_col = config->n_col;
        }
      }
      expr[i_out] = '\0';
      rc = __fts5_expr_new(config, and, i_col, expr, pp,config->errmsg);
    }else{
      *pp = 0;
    }
    dbsql_free(expr);
  }

  return rc;
}

